with cleaned as (select id, order_id, carrier, shipped_date, status, concat_ws('-', status, carrier) as status_carrier_key from shipments where status = 'IN_TRANSIT'), filtered as (select *, initcap(trim(carrier)) as carrier_title, coalesce(carrier, 'OTHER') as carrier_filled from cleaned where shipped_date between '2023-11-01' and '2024-08-01'), with_windows as (select *, row_number() over (partition by order_id order by shipped_date asc, id asc) as row_seq, first_value(carrier) ignore nulls over (partition by carrier order by shipped_date asc, id asc rows between unbounded preceding and current row) as first_known_carrier, first_value(carrier, true) over (partition by month(shipped_date) order by shipped_date asc, id asc rows between unbounded preceding and current row) as first_known_carrier_2 from filtered), metrics as (select *, row_number() over (partition by month(shipped_date) order by shipped_date asc, id asc) as event_seq, lag(row_seq, 2) over (partition by order_id order by shipped_date asc, id asc) as prev_row_seq, dense_rank() over (order by row_seq asc) as row_seq_dense_rank from with_windows where order_id in (10, 11)) select case when row_seq_dense_rank >= 9 then 'PREMIUM' else 'STANDARD' end as row_seq_dense_rank_tier, count(distinct status) as distinct_status, count_if(carrier = 'Flash') as flash_events, count(case when status = 'RETURNED' then 1 end) as returned_count from metrics group by rollup (case when row_seq_dense_rank >= 9 then 'PREMIUM' else 'STANDARD' end) order by row_seq_dense_rank_tier desc nulls last;
